{"summary": "Create stylesheet for layout, table, tooltip, and selection", "command": "create", "path": "/root/output/css/style.css", "file_text": "/* Layout */
:root {
  --bg: #0b1020;
  --panel: #111a33;
  --text: #e8ecff;
  --muted: #a9b4dd;
  --grid: rgba(255, 255, 255, 0.12);
  --selected: rgba(255, 213, 79, 0.22);
}

html, body {
  height: 100%;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
  background: radial-gradient(1200px 700px at 10% 0%, #17224a 0%, var(--bg) 55%);
  color: var(--text);
}

.header {
  padding: 18px 22px 10px;
  border-bottom: 1px solid var(--grid);
}

.header h1 {
  margin: 0;
  font-size: 18px;
  font-weight: 650;
  letter-spacing: 0.2px;
}

.subtitle {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.layout {
  display: flex;
  gap: 14px;
  padding: 14px;
  align-items: stretch;
  height: calc(100% - 72px);
  box-sizing: border-box;
}

.panel {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.02));
  border: 1px solid var(--grid);
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

#bubble-panel {
  flex: 1.15;
  min-width: 520px;
}

#table-panel {
  flex: 0.85;
  min-width: 440px;
}

.panel-header {
  padding: 12px 14px;
  border-bottom: 1px solid var(--grid);
  display: flex;
  gap: 12px;
  align-items: baseline;
  justify-content: space-between;
}

.panel-header h2 {
  margin: 0;
  font-size: 14px;
  font-weight: 650;
}

.hint {
  font-size: 12px;
  color: var(--muted);
}

.chart-wrap {
  padding: 10px;
  flex: 1;
}

#bubble-svg {
  width: 100%;
  height: 100%;
  min-height: 520px;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: flex-end;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--muted);
  white-space: nowrap;
}

.legend-swatch {
  width: 10px;
  height: 10px;
  border-radius: 2px;
  border: 1px solid rgba(255, 255, 255, 0.25);
}

/* Table */
.table-wrap {
  overflow: auto;
  padding: 10px;
  flex: 1;
}

#stocks-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}

#stocks-table thead th {
  position: sticky;
  top: 0;
  background: rgba(17, 26, 51, 0.96);
  backdrop-filter: blur(4px);
  text-align: left;
  padding: 10px 10px;
  border-bottom: 1px solid var(--grid);
}

#stocks-table td {
  padding: 8px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  vertical-align: top;
}

#stocks-table td.num,
#stocks-table th.num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

#stocks-table tbody tr {
  cursor: pointer;
}

#stocks-table tbody tr:hover {
  background: rgba(255, 255, 255, 0.04);
}

#stocks-table tbody tr.selected {
  background: var(--selected);
  outline: 1px solid rgba(255, 213, 79, 0.45);
}

/* Bubble chart */
.node circle {
  stroke: rgba(255, 255, 255, 0.7);
  stroke-width: 1px;
}

.node.selected circle {
  stroke: rgba(255, 213, 79, 1);
  stroke-width: 3px;
}

.node text {
  fill: rgba(255, 255, 255, 0.95);
  font-weight: 700;
  letter-spacing: 0.2px;
  text-anchor: middle;
  dominant-baseline: middle;
  pointer-events: none;
  user-select: none;
}

/* Tooltip */
.tooltip {
  position: absolute;
  padding: 10px 10px;
  background: rgba(0, 0, 0, 0.82);
  color: white;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  pointer-events: none;
  opacity: 0;
  transform: translateY(2px);
  transition: opacity 120ms ease, transform 120ms ease;
  font-size: 12px;
  max-width: 280px;
  line-height: 1.25;
}

.tooltip.visible {
  opacity: 1;
  transform: translateY(0px);
}

.tooltip .title {
  font-weight: 700;
  margin-bottom: 4px;
}

.tooltip .muted {
  color: rgba(255, 255, 255, 0.78);
}
"}

