.tooltip.visible {
  opacity: 1;
  transform: translateY(0px);
}

.tooltip .title {
  font-weight: 700;
  margin-bottom: 4px;
}

.tooltip .muted {
  color: rgba(255, 255, 255, 0.78);
}
