{"summary": "Create stylesheet for layout, table, tooltip, and selection", "command": "create", "path": "/root/output/css/style.css", "file_text": "/* Layout */
:root {
  --bg: #0b1020;
  --panel: #111a33;
  --text: #e8ecff;
  --muted: #a9b4dd;
  --grid: rgba(255, 255, 255, 0.12);
  --selected: rgba(255, 213, 79, 0.22);
}

html, body {
  height: 100%;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
  background: radial-gradient(1200px 700px at 10% 0%, #17224a 0%, var(--bg) 55%);
  color: var(--text);
}

.header {
  padding: 18px 22px 10px;
  border-bottom: 1px solid var(--grid);
}

.header h1 {
  margin: 0;
  font-size: 18px;
  font-weight: 650;
  letter-spacing: 0.2px;
}

.subtitle {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.layout {
  display: flex;
  gap: 14px;
  padding: 14px;
  align-items: stretch;
  height: calc(100% - 72px);
  box-sizing: border-box;
}

.panel {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.02));
  border: 1px solid var(--grid);
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

#bubble-panel {
  flex: 1.15;
  min-width: 520px;
}

#table-panel {
  flex: 0.85;
  min-width: 440px;
}

.panel-header {
  padding: 12px 14px;
  border-bottom: 1px solid var(--grid);
  display: flex;
  gap: 12px;
  align-items: baseline;
  justify-content: space-between;
}

.panel-header h2 {
  margin: 0;
  font-size: 14px;
  font-weight: 650;
}

.hint {
  font-size: 12px;
  color: var(--muted);
}

.chart-wrap {
  padding: 10px;
  flex: 1;
}

#bubble-svg {
  width: 100%;
  height: 100%;
  min-height: 520px;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: flex-end;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--muted);
  white-space: nowrap;
}

.legend-swatch {
  width: 10px;
  height: 10px;
  border-radius: 2px;
  border: 1px solid rgba(255, 255, 255, 0.25);
}

/* Table */
.table-wrap {
  overflow: auto;
  padding: 10px;
  flex: 1;
}

#stocks-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}

#stocks-table thead th {
  position: sticky;
  top: 0;
  background: rgba(17, 26, 51, 0.96);
  backdrop-filter: blur(4px);
  text-align: left;
  padding: 10px 10px;
  border-bottom: 1px solid var(--grid);
}

#stocks-table td {
  padding: 8px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  vertical-align: top;
}

#stocks-table td.num,
#stocks-table th.num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

#stocks-table tbody tr {
  cursor: pointer;
}

#stocks-table tbody tr:hover {
  background: rgba(255, 255, 255, 0.04);
}

#stocks-table tbody tr.selected {
  background: var(--selected);
  outline: 1px solid rgba(255, 213, 79, 0.45);
}

/* Bubble chart */
.node circle {
  stroke: rgba(255, 255, 255, 0.7);
  stroke-width: 1px;
}

.node.selected circle {
  stroke: rgba(255, 213, 79, 1);
  stroke-width: 3px;
}

.node text {
  fill: rgba(255, 255, 255, 0.95);
  font-weight: 700;
  letter-spacing: 0.2px;
  text-anchor: middle;
  dominant-baseline: middle;
  pointer-events: none;
  user-select: none;
}

/* Tooltip */
.tooltip {
  position: absolute;
  padding: 10px 10px;
  background: rgba(0, 0, 0, 0.82);
  color: white;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  pointer-events: none;
  opacity: 0;
  transform: translateY(2px);
  transition: opacity 120ms ease, transform 120ms ease;
  font-size: 12px;
  max-width: 280px;
  line-height: 1.25;
}

.tooltip.visible {
  opacity: 1;
  transform: translateY(0px);
}

.tooltip .title {
  font-weight: 700;
  margin-bottom: 4px;
}

.tooltip .muted {
  color: rgba(255, 255, 255, 0.78);
}
"}

{"summary": "Create D3 visualization logic for bubble chart, legend, table linking", "command": "create", "path": "/root/output/js/visualization.js", "file_text": "/* global d3 */
(function () {
  const WIDTH = 760;
  const HEIGHT = 580;
  const MARGIN = { top: 10, right: 10, bottom: 10, left: 10 };

  const svg = d3
    .select('#bubble-svg')
    .attr('viewBox', `0 0 ${WIDTH} ${HEIGHT}`)
    .attr('preserveAspectRatio', 'xMidYMid meet');

  const tooltip = d3.select('#tooltip');

  const rootG = svg.append('g').attr('transform', `translate(${MARGIN.left},${MARGIN.top})`);
  const innerW = WIDTH - MARGIN.left - MARGIN.right;
  const innerH = HEIGHT - MARGIN.top - MARGIN.bottom;

  function formatMarketCap(value) {
    if (!Number.isFinite(value)) return '';
    const abs = Math.abs(value);
    if (abs >= 1e12) return `${(value / 1e12).toFixed(2)}T`;
    if (abs >= 1e9) return `${(value / 1e9).toFixed(2)}B`;
    if (abs >= 1e6) return `${(value / 1e6).toFixed(2)}M`;
    return d3.format(',.0f')(value);
  }

  function isEtfRow(d) {
    // The dataset encodes ETFs with missing marketCap/country/website.
    return d.sector === 'ETF' || !Number.isFinite(d.marketCap);
  }

  function showTooltip(event, d) {
    if (isEtfRow(d)) return;

    tooltip
      .classed('visible', true)
      .attr('aria-hidden', 'false')
      .html(
        `<div class="title">${d.ticker} <span class="muted">(${d.sector})</span></div>` +
          `<div>${d.name}</div>`
      );

    moveTooltip(event);
  }

  function moveTooltip(event) {
    const pad = 12;
    const w = tooltip.node().offsetWidth;
    const h = tooltip.node().offsetHeight;

    let x = event.pageX + pad;
    let y = event.pageY - h - pad;

    const maxX = window.scrollX + document.documentElement.clientWidth - w - 6;
    const minX = window.scrollX + 6;
    x = Math.max(minX, Math.min(maxX, x));

    const minY = window.scrollY + 6;
    const maxY = window.scrollY + document.documentElement.clientHeight - h - 6;
    y = Math.max(minY, Math.min(maxY, y));

    tooltip.style('left', `${x}px`).style('top', `${y}px`);
  }

  function hideTooltip() {
    tooltip.classed('visible', false).attr('aria-hidden', 'true');
  }

  let selectedTicker = null;
  let rowSelection = null;
  let nodeSelection = null;

  function setSelected(ticker) {
    selectedTicker = ticker;

    if (rowSelection) {
      rowSelection.classed('selected', (d) => d.ticker === selectedTicker);

      if (selectedTicker) {
        const row = rowSelection.filter((d) => d.ticker === selectedTicker).node();
        if (row) row.scrollIntoView({ block: 'nearest' });
      }
    }

    if (nodeSelection) {
      nodeSelection.classed('selected', (d) => d.ticker === selectedTicker);
    }
  }

  d3.csv('data/stock-descriptions.csv', (row) => {
    const ticker = (row.ticker || '').trim();
    const sector = (row.sector || '').trim();
    const name = (row['full name'] || '').trim();

    const mcRaw = (row.marketCap || '').trim();
    const marketCap = mcRaw === '' ? NaN : +mcRaw;

    return {
      ticker,
      sector,
      name,
      marketCap
    };
  }).then((raw) => {
    const data = raw
      .filter((d) => d.ticker)
      .sort((a, b) => d3.ascending(a.sector, b.sector) || d3.ascending(a.ticker, b.ticker));

    const sectors = Array.from(new Set(data.map((d) => d.sector))).sort(d3.ascending);

    const color = d3
      .scaleOrdinal()
      .domain(sectors)
      .range(d3.schemeTableau10.concat(d3.schemeSet3).slice(0, sectors.length));

    // Legend
    const legend = d3.select('#legend');
    const legendItems = legend
      .selectAll('.legend-item')
      .data(sectors)
      .enter()
      .append('div')
      .attr('class', 'legend-item');

    legendItems
      .append('span')
      .attr('class', 'legend-swatch')
      .style('background', (d) => color(d));

    legendItems.append('span').text((d) => d);

    // Radius scale (ETFs uniform)
    const caps = data.map((d) => d.marketCap).filter((v) => Number.isFinite(v));
    const capExtent = d3.extent(caps);

    const rScale = d3
      .scaleSqrt()
      .domain(capExtent)
      .range([12, 52]);

    const ETF_R = 16;

    const nodes = data.map((d) => ({
      ...d,
      r: isEtfRow(d) ? ETF_R : rScale(d.marketCap)
    }));

    // Sector cluster centers: equally spaced around a small ring, kept near chart center.
    const cx = innerW / 2;
    const cy = innerH / 2;
    const ringR = Math.min(innerW, innerH) * 0.18;

    const centerBySector = new Map(
      sectors.map((s, i) => {
        const a = (2 * Math.PI * i) / sectors.length - Math.PI / 2;
        return [s, { x: cx + ringR * Math.cos(a), y: cy + ringR * Math.sin(a) }];
      })
    );

    // Deterministic initial positions (avoid Math.random() inside simulation).
    nodes.forEach((d, i) => {
      const c = centerBySector.get(d.sector) || { x: cx, y: cy };
      const gx = (i % 10) - 4.5;
      const gy = (Math.floor(i / 10) % 10) - 4.5;
      d.x = c.x + gx * 6;
      d.y = c.y + gy * 6;
    });

    const simulation = d3
      .forceSimulation(nodes)
      .force('center', d3.forceCenter(cx, cy))
      .force(
        'x',
        d3
          .forceX((d) => (centerBySector.get(d.sector) || { x: cx }).x)
          .strength(0.12)
      )
      .force(
        'y',
        d3
          .forceY((d) => (centerBySector.get(d.sector) || { y: cy }).y)
          .strength(0.12)
      )
      .force('collide', d3.forceCollide((d) => d.r + 1.5).iterations(2))
      .force('charge', d3.forceManyBody().strength(-3));

    // Deterministic final layout: tick a fixed number of steps, then render once.
    const TICKS = 420;
    for (let i = 0; i < TICKS; i++) simulation.tick();
    simulation.stop();

    // Clamp into view bounds (soft safety).
    nodes.forEach((d) => {
      d.x = Math.max(d.r, Math.min(innerW - d.r, d.x));
      d.y = Math.max(d.r, Math.min(innerH - d.r, d.y));
    });

    // Bubbles
    nodeSelection = rootG
      .selectAll('g.node')
      .data(nodes, (d) => d.ticker)
      .enter()
      .append('g')
      .attr('class', 'node')
      .attr('transform', (d) => `translate(${d.x},${d.y})`)
      .on('mouseenter', function (event, d) {
        showTooltip(event, d);
        d3.select(this).raise();
      })
      .on('mousemove', function (event, d) {
        if (!isEtfRow(d)) moveTooltip(event);
      })
      .on('mouseleave', function () {
        hideTooltip();
      })
      .on('click', function (event, d) {
        event.preventDefault();
        setSelected(d.ticker);
      });

    nodeSelection
      .append('circle')
      .attr('r', (d) => d.r)
      .attr('fill', (d) => color(d.sector))
      .attr('fill-opacity', 0.92);

    nodeSelection
      .append('text')
      .text((d) => d.ticker)
      .style('font-size', (d) => `${Math.max(9, Math.min(14, d.r * 0.7))}px`);

    // Table
    const tbody = d3.select('#stocks-table tbody');

    rowSelection = tbody
      .selectAll('tr')
      .data(nodes, (d) => d.ticker)
      .enter()
      .append('tr')
      .on('click', function (event, d) {
        event.preventDefault();
        setSelected(d.ticker);
      });

    rowSelection.append('td').text((d) => d.ticker);
    rowSelection.append('td').text((d) => d.name);
    rowSelection.append('td').text((d) => d.sector);
    rowSelection
      .append('td')
      .attr('class', 'num')
      .text((d) => (isEtfRow(d) ? '' : formatMarketCap(d.marketCap)));

    // Initial selection (none)
    setSelected(null);
  });
})();
"}

